use strict; use warnings;
my $root="/bench/repo";
# map import path -> package short name from non-test internal files
my %pkg_of_import;
sub walk { my ($d,$cb)=@_; return unless -d $d; opendir my $dh,$d or return; while(my $e=readdir $dh){ next if $e eq "."||".."; my $p="$d/$e"; -d $p ? walk($p,$cb) : $cb->($p) if -f $p } }
walk("$root/internal", sub {
  my $p=shift; return unless $p=~/\.go$/ && $p!~/_test\.go$/;
  open my $f,"<",$p or return; my $pkg; while(<$f>){ if(/^package (\w+)/){$pkg=$1; last} } close $f;
  (my $rel=$p)=~s|^\Q$root/\E||; my $imp="github.com/usememos/memos/$rel"; $imp=~s|/[^/]+$||;
  $pkg_of_import{$imp}=$pkg;
});
# collect decls
my @decls;
walk("$root/internal", sub {
  my $path=shift; return unless $path=~/\.go$/ && $path!~/_test\.go$/;
  open my $f,"<",$path or return; my @lines=<$f>; close $f;
  my $pkg; for(@lines){$pkg=$1 if /^package (\w+)/}
  (my $rel=$path)=~s|^\Q$root/\E||; my $imp="github.com/usememos/memos/$rel"; $imp=~s|/[^/]+$||;
  for my $i (0..$#lines){
    next unless $lines[$i]=~/^func (?:\([^)]+\)\s+)?(\w+)\(/;
    push @decls,{sym=>$1,pkg=>$pkg,imp=>$imp,path=>$path,line=>$i+1};
  }
});
# all go files
my @files; walk($root, sub { push @files, shift if $_[0]=~/\.go$/ });
# build import map per file: alias -> import path for internal/usememos
my @rank;
for my $d (@decls) {
  my $sym=$d->{sym}; my $ipkg=$d->{pkg}; my $imp=$d->{imp};
  my $total=0; my %fc;
  for my $file (@files) {
    open my $f,"<",$file or next; my @lines=<$f>; close $f;
