      $n += () = $content =~ /(?<![\.\w])$q\s*\(/g;
      $n -= 1 if $file eq $d->{path}; # subtract def line roughly - imprecise
    }
    if($n>0){ $total+=$n; $fc{$file}=1; }
  }
  push @rank,{total=>$total,files=>scalar keys %fc,d=>$d};
}
@rank=sort{$b->{total}<=>$a->{total}||$b->{files}<=>$a->{files}}@rank;
